    /** Audits one trace and returns its result object. */
    public Map<String, Object> audit(Main.Trace trace) {
        init(trace);
        List<Main.Event> events = trace.events;
        for (int index = 0; index < events.size(); index++) {
            Main.Event event = events.get(index);
            if (event.keys != null) {
                applyKeys(event.keys);
            } else {
                processDatagram(index, event);
